class City(BaseModel):
    vk_id: int
    name: str
    region: str | None


def get_one(city_id: int) -> City:
    return City(
        vk_id=city_id,
        name=cities[city_id][0],
        region=cities[city_id][1],
    )


def get_many(cities_ids: list) -> list[City]:
    return [
        City(vk_id=k, name=v[0], region=v[1])
        for k, v in cities.items()
        if k in cities_ids
    ]


def autocomplete(val: str) -> list[City]:
    val_lower = val.lower()
    return [
        City(vk_id=k, name=v[0], region=v[1])
        for k, v in cities.items()
        if v[0].lower().startswith(val_lower)
    ]

if __name__ == "__main__":
    import json
    data = [[city_id, name, region] for city_id, (name, region) in cities.items()]
    with open('cities.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, separators=(',', ':'))
